import json, sys
from decimal import Decimal, localcontext
from datetime import datetime, timedelta
data = json.load(sys.stdin)
sys.path.insert(0, data["support"])
namespace = {"__name__": "more_itertools.more", "__package__": "more_itertools", "__file__": "<frozen-source>"}
exec(compile(data["source"], "<frozen-source>", "exec"), namespace)
cls = namespace["numeric_range"]
rows = []
with localcontext() as context:
    context.prec = 2
    cases = [("finite_float_huge_range", (0.0, 1e308, 1e-308), 0.0, 0), ("decimal_precision_2", (Decimal(0), Decimal(10), Decimal("0.1")), Decimal(0), 0), ("finite_float_nonstart", (0.0, 1e308, 1e-308), 1e-308, 1), ("decimal_nonstart", (Decimal(0), Decimal(10), Decimal("0.1")), Decimal("0.1"), 1)]
    for name, args, query, expected_index in cases:
        for operation in ("contains", "index"):
            if data.get("case_filter") != [name, operation]:
                continue
            try:
                instance = cls(*args)
                value = (query in instance) if operation == "contains" else instance.index(query)
                correct = (value is True) if operation == "contains" else (type(value) is int and value == expected_index)
                rows.append({"case": name, "operation": operation, "passed": correct, "value": repr(value), "expected_index": expected_index})
            except Exception as error:
                rows.append({"case": name, "operation": operation, "passed": False, "exception": type(error).__name__, "message": str(error)})
date_cases = [("datetime_upper_bound", (datetime.max - timedelta(days=1), datetime.max, timedelta(days=2))), ("datetime_lower_bound", (datetime.min + timedelta(days=1), datetime.min, -timedelta(days=2)))]
for name, args in date_cases:
    for operation in ("len", "first"):
        if data.get("case_filter") != [name, operation]:
            continue
        try:
            instance = cls(*args)
            value = len(instance) if operation == "len" else instance[0]
            correct = value == (1 if operation == "len" else args[0])
            rows.append({"case": name, "operation": operation, "passed": correct, "value": repr(value)})
        except Exception as error:
            rows.append({"case": name, "operation": operation, "passed": False, "exception": type(error).__name__, "message": str(error)})
nonmembers = [("datetime_upper_nonmember", (datetime.max - timedelta(days=1), datetime.max, timedelta(days=2)), datetime.max - timedelta(hours=12)), ("datetime_lower_nonmember", (datetime.min + timedelta(days=1), datetime.min, -timedelta(days=2)), datetime.min + timedelta(hours=12))]
for name, args, query in nonmembers:
    for operation in ("contains", "index"):
        if data.get("case_filter") != [name, operation]:
            continue
        try:
            instance = cls(*args)
        except Exception as error:
            rows.append({"case": name, "operation": operation, "passed": False, "constructor_exception": type(error).__name__})
            continue
        try:
            value = query in instance if operation == "contains" else instance.index(query)
            rows.append({"case": name, "operation": operation, "passed": value is False if operation == "contains" else False, "value": repr(value)})
        except Exception as error:
            rows.append({"case": name, "operation": operation, "passed": operation == "index" and isinstance(error, ValueError), "exception": type(error).__name__, "message": str(error)})
print(json.dumps(rows))

import json,sys
from decimal import Decimal,localcontext,Rounded
from itertools import islice
d=json.load(sys.stdin)
sys.path.insert(0,d["support"])
ns={"__name__":"more_itertools.more","__package__":"more_itertools","__file__":"<frozen-source>"}
exec(compile(d["source"],"<frozen-source>","exec"),ns)
try:
    if d["kind"]=="mixed_promotion":
        sign=d["direction"]
        start=sign*(2**53+1)
        stop=sign*(2**53+6)
        step=sign*1.0
        expected=[]
        for i in range(16):
            value=start+i*step
            if value<stop if sign==1 else value>stop:
                expected.append(value)
            else:
                break
        else:
            raise AssertionError("independent small enumeration did not terminate")
        assert len(expected)==6
        r=ns["numeric_range"](start,stop,step)
        if d["operation"]=="sequence":
            actual=list(islice(iter(r),17))
            ok=actual==expected
            value=repr(actual)
        elif d["operation"]=="len":
            value=len(r)
            ok=type(value) is int and value==len(expected)
        elif d["operation"]=="contains":
            value=expected[0] in r
            ok=value is True
        else:
            value=r.index(expected[0])
            ok=type(value) is int and value==0
    else:
        with localcontext() as ctx:
            ctx.prec=2
            ctx.traps[Rounded]=True
            r=ns["numeric_range"](Decimal(1),Decimal(2),Decimal(".001"))
            if d["operation"]=="contains":
                value=Decimal(1) in r
                ok=value is True
            else:
                value=r.index(Decimal(1))
                ok=type(value) is int and value==0
    row={"passed":ok,"value":repr(value)}
except Exception as e:
    row={"passed":False,"exception":type(e).__name__,"message":str(e)}
print(json.dumps(row))

